selected.compute:
options = read('/input/options')
ids = [option['id'] for option in options]
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for choice in combinations(ids, size):
        candidate = list(choice)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

selected.effects:
artifact = read('/output/selection')
if artifact:
    selection = artifact
    if not valid(selection):
        selection = result
else:
    selection = result
    write('/output/selection', selection)
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
